const fullText = $('ExtractFromFile').first().json.text;

// Splitte an '---' Trennzeichen (wie in FPCSamplesV2.md)
const blocks = fullText
  .split(/\n---\n/)
  .map(b => b.trim())
  .filter(b => b.length > 0);

return blocks.map(block => ({ json: { block } }));

const items = $input.all();
const output = [];

for (const item of items) {
  const block = item.json.block;

  // Titel extrahieren: erste ### Zeile
  const titleMatch = block.match(/^###\s+(.+)$/m);
  const title = titleMatch ? titleMatch[1].trim() : '';
  if (!title) continue; // Bloecke ohne Titel ueberspringen (z.B. Kategorie-Header)

  // Kategorie extrahieren: **Kategorie**: XYZ
  const catMatch = block.match(/\*\*Kategorie\*\*:\s*(.+?)$/m);
  const category = catMatch ? catMatch[1].trim() : 'Allgemein';

  // Level extrahieren: **Level**: XYZ
  const levelMatch = block.match(/\*\*Level\*\*:\s*(.+?)$/m);
  const level = levelMatch ? levelMatch[1].trim() : 'Mittel';

  // Beschreibung extrahieren
  const descMatch = block.match(/\*\*Beschreibung\*\*:\s*(.+?)$/m);
  const description = descMatch ? descMatch[1].trim() : '';

  // Anwendung extrahieren
  const appMatch = block.match(/\*\*Anwendung\*\*:\s*(.+?)$/m);
  const application = appMatch ? appMatch[1].trim() : '';

  // Code-Block extrahieren
  const codeMatch = block.match(/```\n([\s\S]*?)```/);
  const code = codeMatch ? codeMatch[1].trim() : '';

  // FPC-Befehle aus dem Code extrahieren
  let commands = '';
  if (code) {
    const codeLines = code.split('\n')
      .map(l => l.trim())
      .filter(l => l && !l.startsWith('#'));
    const cmds = [...new Set(codeLines.map(l => l.split(/\s+/)[0].toUpperCase()))];
    commands = cmds.join(', ');
  }

  // Tags extrahieren (aus Tags: Zeile oder aus Titel + Befehle)
  const tagsMatch = block.match(/Tags:\s*(.+?)$/m);
  let tags = tagsMatch ? tagsMatch[1].trim() : '';
  if (!tags) {
    // Auto-Tags aus Titel und Befehlen
    const words = title.split(/[\s–—()]+/).filter(w => w.length > 2);
    tags = [...new Set([...words, ...commands.split(', ')])].join(', ');
  }

  // Testfaelle extrahieren
  const testLines = block.split('\n')
    .filter(l => l.match(/^-\s+(I\d|Test)/i))
    .map(l => l.trim());
  const testCases = testLines.join('\n');

  // Hinweise/Warnungen extrahieren
  const warnings = block.split('\n')
    .filter(l => l.match(/^(WICHTIG|WARNUNG|Problem|LÖSUNG|Hinweis|ACHTUNG|DIESES|NIE\s)/i))
    .map(l => l.trim())
    .join('\n');

  // Text fuer Embedding zusammenbauen
  let textForEmbedding = '';
  textForEmbedding += `${title}.\n`;
  if (description) textForEmbedding += `${description}\n`;
  if (application) textForEmbedding += `Anwendung: ${application}\n`;
  if (code) textForEmbedding += `\nCode:\n${code}\n`;
  if (testCases) textForEmbedding += `\nTestfaelle:\n${testCases}\n`;
  if (warnings) textForEmbedding += `\n${warnings}\n`;

  output.push({
    json: {
      title,
      category,
      level,
      description,
      application,
      code,
      commands,
      tags,
      testCases,
      warnings,
      textForEmbedding
    }
  });
}

return output;
